; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		bootstrap.asm
;		Purpose:	Per-program bootstrap streamed into a "resident runtime" (SHARED) compile.
;		Created:	17th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		When GPC.INPUT's 4th line selects SHARED mode, a compiled program carries NO embedded
;		runtime. Instead WriteObjectCode (object.asm) streams this template as the program's first
;		255 bytes ($0801..$08FF), followed by the p-code at $0900. On RUN, BASIC's SYS 2069 enters
;		BootEntry, which:
;
;			1. checks the 4-byte magic at RTBASE -- is the shared runtime already resident?
;			2. if not, LOADs GPB/GPC.RT.nnn.BIN to its own home with secondary address 1,
;			   trying the current directory first and then the root of the SD card;
;			3. enters the resident runtime at RT_ENTRY, handing it this program's p-code page,
;			   workspace start (patched per program) and workspace end.
;
;		So any program brings the runtime up if it is missing, and reuses it if it is already
;		there -- one runtime on disk, loaded once in memory.
;
;		This template runs at $0801 but is STORED up in compiler space (it is globbed into the
;		application _library.asm, linked above ObjectBase). `.logical $0801 ... .here` makes 64tass
;		resolve every label inside to $08xx while placing the physical bytes in compiler space, so
;		the streamed bytes are correct for execution at $0801 after reload. object.asm streams from
;		the PHYSICAL labels ProgramBootstrap..ProgramBootstrapEnd and patches the one WS_START byte
;		at BootWSPatchOffset. The compiler's own $0801 entry (00main.header) is untouched -- this is
;		inert data the compiler only writes to disk, never executes.
;
; ************************************************************************************************

		.section code

ProgramBootstrap: 							; PHYSICAL label (compiler space) -- object.asm streams here
		.logical $0801

; ------------------------------------------------------------------------------------------------
;		BASIC stub -- byte-identical to StartBasicProgram (00main.header): 10 SYS 2069:REM GPC!
; ------------------------------------------------------------------------------------------------
		.word 	$0813 						; link -> the end-of-program marker at $0813
		.word 	10 							; line number
		.byte 	$9E 						; SYS token
		.text 	' 2069' 					; space, $0815 in decimal
		.byte 	$3A 						; ':' statement separator
		.byte 	$8F 						; REM token
		.text 	' GPC!' 					; compiler signature -- shows on LIST
		.byte 	0 							; end of line
		.word 	0 							; end of program

; ------------------------------------------------------------------------------------------------
;		SYS 2069 lands here ($0815).
; ------------------------------------------------------------------------------------------------
BootEntry:
		.cerror BootEntry != $0815, "bootstrap SYS entry is not at $0815 -- BASIC stub size drifted"
		;
		;		Is the shared runtime already resident? Compare the 4 magic bytes at RTBASE.
		;
		ldx 	#3
_BBCheck:
		lda 	RTBASE,x
		cmp 	BBMagic,x
		bne 	_BBCold
		dex
		bpl 	_BBCheck
		;
		;		The core is up. If this program uses no GPB keyword that is the whole question, but if
		;		it does it must ALSO find the handlers, and a core-only load leaves the core magic
		;		looking exactly the same. So check the second magic below RTBASE as well. Getting this
		;		wrong is not a crash here -- it is a jump into a workspace at the first GPB keyword.
		;
		;		The three per-program bytes are DATA at the end of this template, not immediates in the
		;		code. They have to be: a global label between a "_" branch and its target splits the
		;		local scope in two and the branch stops resolving -- the same trap BBTryLoad's own note
		;		describes, and it cost a build here.
		;
		lda 	BBNeedGP 					; 0 = no GPB keyword, 1 = uses them
		beq 	_BBEnter 					; WARM -- core is all this program needs
		ldx 	#3
_BBCheckGP:
		lda 	RTGPMAGIC,x
		cmp 	BBGPMagic,x
		bne 	_BBCold
		dex
		bpl 	_BBCheckGP
		bra 	_BBEnter 					; WARM -- handlers are up too
_BBCold:
		;
		;		Cold: LOAD the runtime to its own home. Try the CURRENT DIRECTORY first, then the
		;		ROOT of the SD card -- a program run from its own folder finds a runtime sitting
		;		beside it, and otherwise falls back to one copy kept at the root, so every folder
		;		on the card does not need its own 11K duplicate. A leading "/" is what addresses
		;		the root (measured on R49 from inside a subdirectory: "GPC.RT.001.BIN" is not
		;		found, "/GPC.RT.001.BIN" loads). The two names overlap in one string -- BBNameRoot
		;		is just BBName with the "/" in front of it.
		;
		;
		;		Which file: the FULL one (handlers + core, loads at RTGPBASE) if this program uses a
		;		GPB keyword, the CORE-ONLY one (loads at RTBASE) if it does not. Loading the full one
		;		always restores both magics, so a program that wanted handlers and found none simply
		;		loads over whatever core was there.
		;
		ldy 	#0 							; which triple: 0 = core only, 3 = full
		lda 	BBNeedGP 					; the same flag the warm check reads
		beq 	_BBPickName
		ldy 	#3
_BBPickName:
		sty 	BBNameIdx
		jsr 	BBLoadLocal
		bcc 	_BBEnter 					; carry clear = loaded OK
		jsr 	BBLoadRoot 					; else the copy at the root of the card
		bcc 	_BBEnter
		;
		;		Neither copy is on the disk. Print a short notice and drop back to BASIC READY --
		;		no runtime is up, so there is no runtime error path to take.
		;
		ldx 	#0
_BBErr:
		lda 	BBErrText,x
		beq 	_BBErrDone
		phx
		jsr 	X16_CHROUT
		plx
		inx
		bne 	_BBErr
_BBErrDone:
		rts 								; return to the SYS caller -> BASIC READY

; ------------------------------------------------------------------------------------------------
;		Hand off to the resident runtime. Both cold and warm paths funnel through here, so the
;		SYS return address is preserved on the stack -- an END in the program RTSes cleanly back
;		to BASIC, exactly as an embedded program does.
; ------------------------------------------------------------------------------------------------
_BBEnter:
		;
		;		A core-only program is about to use the memory the GPB handlers occupy -- its workspace
		;		runs all the way up to RTBASE -- so it must first say so, by wiping RTGPMAGIC.
		;
		;		UNCONDITIONALLY, warm path included, and that is the whole point. It is not enough to
		;		wipe it when the core file is LOADED: the common sequence is a GPB program bringing the
		;		full runtime up, then a core-only program entering it warm and quietly overwriting the
		;		handlers, then a third program wanting them. Nothing was loaded in the middle of that,
		;		so a load-time wipe would never fire and the third program would enter handlers that
		;		had been eaten.
		;
		;		Nor is it safe to let the workspace overwrite the magic by chance: it sits in the top
		;		four bytes of that space, so whether it actually gets written depends on how much RAM
		;		the program uses. Handlers destroyed with the magic left standing is exactly the lie
		;		this check exists to prevent, so it is done on purpose rather than hoped for.
		;
		;		Cost is that the next GPB program always reloads. That is correct, not wasteful -- the
		;		handlers really were thrown away.
		;
		lda 	BBNeedGP
		bne 	_BBGo 						; a GPB program keeps them, and its workspace stops below them
		ldx 	#3
_BBZap:
		stz 	RTGPMAGIC,x 				; stz abs,x rather than lda #0 / sta abs,x -- two bytes, and
		dex 								; the padding below is where GP.BANKED's copy loop went
		bpl 	_BBZap
_BBGo:
		;
		;		A GP.BANKED region ships at the TOP of the p-code, page aligned, and belongs at
		;		$A000 in the bank the program named. Move it there and LEAVE THE BANK SELECTED:
		;		that window is where the code runs for the life of the program.
		;
		;		ONCE PER LOAD, NOT PER RUN. The workspace starts where the region was -- that is
		;		the whole point of putting it at the top -- so by the time a second RUN reaches
		;		here those bytes are variables and strings. Zeroing the page count makes the
		;		second RUN skip the copy and use what is already in the bank, which is still
		;		exactly what the first one put there.
		;
		;		THREE GLOBAL LABELS, not "_" ones. object.asm patches the source page straight
		;		into BBCodeSrc's operand as the template streams past, and it needs the address
		;		to do it. Everything that branches across them branches to a global too, for the
		;		scope reason BBTryLoad's own note gives.
		;
		ldx 	BBCodePages 				; 0 = this program has no banked region
		beq 	BBCodeSkip
		stz 	BBCodePages
		lda 	BBCodeBank
		sta 	$00
		ldy 	#0 							; and it stays 0 between pages -- the byte loop wraps
BBCodeSrc:
		lda 	$FF00,y 					; source page PATCHED
BBCodeDst:
		sta 	$A000,y
		iny
		bne 	BBCodeSrc
		inc 	BBCodeSrc+2
		inc 	BBCodeDst+2
		dex
		bne 	BBCodeSrc
BBCodeSkip:
		lda 	#PCODE_PAGE 				; A = p-code base page ($09), page-aligned for codePtr
		ldx 	BBWSStart 					; X = workspace start page
		ldy 	BBWSEnd 					; Y = workspace end page -- RTBASE>>8 for a program with no GPB
											; keyword, RTGPBASE>>8 for one with the handlers below it. That
											; difference is the whole point of the split: 2,560 bytes.
		jmp 	RT_ENTRY 					; RTBASE+4 -> jmp StartRuntime

; ------------------------------------------------------------------------------------------------
;		Try to LOAD the runtime under the name in A (length) / X,Y (address). Secondary address 1
;		makes the KERNAL honour the file's own load address (RTBASE), ignoring the address in X/Y.
;		Logical file 0 (file 1 has been seen to hang a later OPEN). Loading high never touches
;		$0801 or the p-code, so this bootstrap survives its own load. Returns carry clear on
;		success, set if the file is not there -- so the caller can just try the next name.
;
;		Sits BELOW _BBEnter deliberately: labels beginning with "_" are local to the enclosing
;		scope in 64tass, and a global label placed between _BBCold and _BBEnter would split that
;		scope in two, leaving the earlier branches referring to an _BBEnter they can no longer see.
; ------------------------------------------------------------------------------------------------
;
;		The four names live in ONE table of (length, lo, hi) triples -- local core, local full,
;		root core, root full -- so picking the file costs one patched byte instead of four copies
;		of the load sequence. X selects local (0) or root (6); BBNameSel adds 0 for core-only or
;		3 for full.
;
BBLoadLocal:
		ldx 	#0
		bra 	BBLoadX
BBLoadRoot:
		ldx 	#6
BBLoadX:
		txa
		clc
		adc 	BBNameIdx 					; 0 = core only, 3 = full -- set by the cold path above
		tax
		ldy 	BBNameTab+2,x 				; Y = name address high
		lda 	BBNameTab+1,x 				; stash the low byte while A is needed for the length
		pha
		lda 	BBNameTab,x 				; A = name length
		plx 								; X = name address low
											; ...and fall straight through: A/X/Y are now exactly what
											; SETNAM wants. The table used to sit between the two, and
											; the "bra BBTryLoad" that jumped it was two of the bytes
											; GP.BANKED's copy loop needed.
BBTryLoad:
		jsr 	X16_SETNAM 					; SETNAM(length in A, name in X/Y)
		lda 	#0 							; SETLFS(logical file 0, device 8, secondary 1)
		ldx 	#8
		ldy 	#1
		jsr 	X16_SETLFS
		lda 	#0 							; LOAD into system memory
		ldx 	#<RTBASE 					; load address (ignored under SA=1, but pass the home)
		ldy 	#>RTBASE
		jmp 	X16_LOAD 					; its carry is our carry

BBNameTab:
			.byte 	BBCoreEnd-BBCore, <BBCore, >BBCore 					; 0  local, core only
			.byte 	BBFullEnd-BBFull, <BBFull, >BBFull 					; 3  local, full
			.byte 	BBCoreEnd-BBCoreRoot, <BBCoreRoot, >BBCoreRoot 	; 6  root, core only
			.byte 	BBFullEnd-BBFullRoot, <BBFullRoot, >BBFullRoot 	; 9  root, full

		;
		;		TWO different numbers here, deliberately, because they answer two questions:
		;
		;		  the MAGIC carries RT_ABI -- "is a runtime already resident, and is it one I can
		;		  enter?" That is an ABI-compatibility question, so it moves only when the layout
		;		  or entry contract changes, and a resident runtime from any build of the same ABI
		;		  is safely reused.
		;
		;		  the FILE NAME carries the engine's BUILD number -- "which runtime file is mine?"
		;		  That pins a compiled program to the exact runtime it was built against.
		;
		;		Both come from a single definition (RT_ABI in common.inc, BuildNumber generated
		;		into version.asm by bumpbuild.py) rather than being spelled out here, so this copy
		;		cannot drift from the runtime's own or from what rtname.py builds.
		;
		;		NOTE the runtime build number is PINNED (rtbuild.txt), not bumped per build -- it
		;		used to bump every time, which renamed the file out from under every already
		;		compiled shared program. Move it only to force a re-pairing, and recompile them
		;		all when you do.
		;
		.cerror RT_ABI > 99, "RT_ABI > 99: the magic's last two bytes are ASCII digits - widen it here and in 00rt.header"
BBMagic:
		.text 	"GP"						; core magic, matched against RTBASE..RTBASE+1
		.byte 	(RT_ABI / 10) + '0' 		; ABI ordinal, two digits, matched against RTBASE+2..3
		.byte 	(RT_ABI - (RT_ABI / 10) * 10) + '0'
BBGPMagic:
		.text 	"GB"						; "handlers loaded too", matched against RTGPMAGIC..+1
		.byte 	(RT_ABI / 10) + '0' 		; same ordinal -- the two halves are one image and one ABI
		.byte 	(RT_ABI - (RT_ABI / 10) * 10) + '0'
		;
		;		One string, two names: the root form is the local form with a "/" in front, so the
		;		fallback costs a single byte rather than a second copy of the name. The name is
		;		formatted, not spelled out, so a build number of any width still comes out right.
		;
BBFullRoot:
		.text 	"/"
BBFull:
		.text 	format("GPB.RT.%03d.BIN", BuildNumber) 	; handlers AND core, loads at RTGPBASE
BBFullEnd:
BBCoreRoot:
		.text 	"/"
BBCore:
		.text 	format("GPC.RT.%03d.BIN", BuildNumber) 	; core only, loads at RTBASE
BBCoreEnd:
BBErrText:
		.text 	"?RT", 13, 0 				; brief -- a full line would wrap in 40 columns

;		The per-program bytes. DATA, not immediates -- see the note at the warm check. The first
;		three are written by WriteObjectCode as the template streams past; BBNameIdx is working
;		state the bootstrap sets itself.
BBWSStart:
		.byte 	$FF 						; workspace start page -- PATCHED
BBWSEnd:
		.byte 	$FF 						; workspace end page (RTBASE or RTGPBASE) -- PATCHED
BBNeedGP:
		.byte 	$FF 						; 0 = no GPB keyword, 1 = uses them -- PATCHED
BBNameIdx:
		.byte 	0 							; which name triple (0 or 3), chosen at run time
BBCodePages:
		.byte 	$FF 						; pages of GP.BANKED region to move, 0 = none -- PATCHED
BBCodeBank:
		.byte 	$FF 						; which bank to move it to -- PATCHED

		.fill 	$0900 - *, 0 				; pad through $08FF so the p-code starts exactly at $0900

		.here
ProgramBootstrapEnd: 						; PHYSICAL end -- (End - Start) == 255 bytes ($0801..$08FF)

BootWSPatchOffset = BBWSStart - $0801 		; offsets of the six per-program bytes within the
BootWSEndPatchOffset = BBWSEnd - $0801 		; streamed template -- object.asm builds its patch
BootGPPatchOffset = BBNeedGP - $0801 		; table from these and nothing else.
BootCodeSrcOffset = BBCodeSrc+2 - $0801 	; ...and the three GP.BANKED needs. The first is an
BootCodePagesOffset = BBCodePages - $0801 	; instruction OPERAND rather than a data byte, which is
BootCodeBankOffset = BBCodeBank - $0801 	; what keeps the copy loop inside the padding.

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		control.asm
;		Purpose:	The compiler's control file, GPC.INPUT
;		Created:	14th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		The compiler had SOURCE.PRG and OBJECT.PRG built into it, so the only way to point it at
;		a program was to rename files around it. It now reads GPC.INPUT, a plain text file of
;		three lines, which is what lets another program drive it:
;
;			DIR.PRG				line 1	the tokenised BASIC to compile
;			C.DIR.PRG			line 2	the object file to write
;								line 3	options. Read, but ignored for now.
;
;		A line ends at CR, at LF, or at anything else below a space, and an empty line is
;		skipped -- so a control file written on a CRLF host is as good as one written on the X16.
;
;		Lowercase is folded to upper. A name typed in ASCII lowercase is not the PETSCII the
;		KERNAL wants, and it is the mistake a caller will actually make; the host filesystems
;		this runs on are all case insensitive, so folding can only ever help.
;
;		There is no fallback. Without a readable GPC.INPUT the compiler says NO GPC.INPUT FILE
;		and stops, because a compiler that guesses at what it was asked to build is worse than
;		one that refuses.
;
; ************************************************************************************************

CFLineSize = 64 							; each line is a fixed 64-byte slot; the four lines are one
CFLineCount = 4 							; contiguous 256-byte block (source, object, map, mode).
											; ReadControlFile counts lines (cfLine) and tracks CR/LF,
											; so an EMPTY line still advances -- an empty line 3 (no
											; map) must not mis-slot line 4 (the mode). Fixed slots
											; mean a single index walks the block with no pointer,
											; which matters because the KERNAL calls here are free
											; to trash zero page.

		.section code

; ************************************************************************************************
;
;		Read GPC.INPUT into SourceFile, ObjectFile and OptionsText.
;
;		Returns carry SET if there was no usable control file.
;
; ************************************************************************************************

ReadControlFile:
		lda 	#0 							; blank all FOUR lines (256 bytes). This zero-terminates
		tax 								; each of them and leaves a short control file holding
_RCFBlank: 									; empty strings rather than whatever was in memory.
		sta 	SourceFile,x
		inx
		bne 	_RCFBlank

		ldy 	#ControlFile >> 8
		ldx 	#ControlFile & $FF
		jsr 	IOOpenRead
		bcs 	_RCFClose 					; no input channel -- reading is NOT harmless: CHRIN would
											; fall back to the keyboard and wait to be typed at.
		ldx 	#0 							; X = write offset (cfLine*CFLineSize + column)
		stz 	cfLine 						; current line, 0..3
		stz 	cfJustCR 					; nonzero => the previous byte was CR (to swallow a CRLF's LF)
_RCFRead:
		jsr 	IOReadByte 					; carry set at end of file
		bcs 	_RCFClose

		cmp 	#' ' 						; CR, LF, and anything else below a space, ends the line
		bcc 	_RCFEndOfLine

		stz 	cfJustCR 					; a real character clears any pending CR
		cmp 	#$C1 						; PETSCII shifted letters ($C1-$DA), what SHIFT-typing gives;
		bcc 	_RCFNotShifted 				; CBM DOS wants the UNshifted bytes in a filename, and they
		cmp 	#$DB 						; are a different character entirely, not a case.
		bcs 	_RCFNotShifted
		and 	#$7F 						; $C1-$DA -> $41-$5A
		bra 	_RCFStore
_RCFNotShifted:
		cmp 	#'a' 						; and ASCII lowercase, which is what a host text editor
		bcc 	_RCFStore 					; gives you
		cmp 	#'z'+1
		bcs 	_RCFStore
		and 	#$DF 						; $61-$7A -> $41-$5A
_RCFStore:
		pha
		txa 								; the last byte of a line is its zero terminator and is
		and 	#CFLineSize-1 				; never written to, so an over-long name is truncated
		cmp 	#CFLineSize-1 				; rather than running on into the next line.
		pla
		bcs 	_RCFRead
		sta 	SourceFile,x
		inx
		bra 	_RCFRead

_RCFEndOfLine: 								; A < ' '
		cmp 	#$0A 						; LF ?
		bne 	_RCFAdvance
		lda 	cfJustCR 					; an LF right after a CR (a CRLF) -> swallow it, do not
		bne 	_RCFSwallow 				; advance again; the CR already ended the line.
_RCFAdvance: 								; CR, a lone LF, or any other control ends the line
		ldy 	#0 							; remember whether this was a CR (so a following LF is eaten)
		cmp 	#$0D
		bne 	_RCFSetCR
		iny
_RCFSetCR:
		sty 	cfJustCR
		inc 	cfLine 						; advance even on an empty line -- so an empty line 3 (no
		lda 	cfLine 						; map) does not mis-slot line 4 (the mode), which the old
		cmp 	#CFLineCount 				; positional walker got wrong.
		bcs 	_RCFClose 					; captured all four lines -> stop, ignore any more
		asl 	a 							; X = cfLine * CFLineSize (64) = start of the next line
		asl 	a
		asl 	a
		asl 	a
		asl 	a
		asl 	a
		tax
		bra 	_RCFRead
_RCFSwallow:
		stz 	cfJustCR
		bra 	_RCFRead

_RCFClose:
		jsr 	IOReadClose 				; close it either way. Logical file 3 is the one the source
											; is read on, so it has to be free.
		sec
		lda 	SourceFile 					; no source name means there was no usable control file:
		beq 	_RCFFail 					; missing, empty, or a first line we could not use. No object
		lda 	ObjectFile 					; name is just as useless -- nowhere to put the answer.
		beq 	_RCFFail 					; Line 4 (the mode) is optional, so it is not checked here.
		clc
_RCFFail:
		rts

; ************************************************************************************************
;
;		"GPC SQUEALING..." and the engine's own build number, then the two names, each on its
;		own labelled line -- the whole of the compiler's startup output. Three short lines so
;		nothing wraps in 40 columns.
;
;			GPC SQUEALING... V0.9.113
;			in:  <source>
;			out: <object>
;
; ************************************************************************************************

PrintWorking:
		ldx 	#WorkingText & $FF 			; "GPC SQUEALING... "
		ldy 	#WorkingText >> 8
		jsr 	PrintMessage
		ldx 	#VersionText & $FF 			; the ENGINE's build number, then CR. It lives here
		ldy 	#VersionText >> 8 			; and not in the front end because the engine is what
		jsr 	PrintMessage 				; compiles -- see scripts/bumpbuild.py
		ldx 	#InText & $FF 				; "in:  "
		ldy 	#InText >> 8
		jsr 	PrintMessage
		ldx 	#0 							; line 1, the source
		jsr 	PrintControlLine
		ldx 	#OutText & $FF 				; CR then "out: "
		ldy 	#OutText >> 8
		jsr 	PrintMessage
		ldx 	#CFLineSize 				; line 2, the object
		jsr 	PrintControlLine
		lda 	#13
		jmp 	$FFD2

; ************************************************************************************************
;
;								There was nothing to work from
;
; ************************************************************************************************

PrintNoControlFile:
		ldx 	#NoControlText & $FF
		ldy 	#NoControlText >> 8
		jmp 	PrintMessage

; ************************************************************************************************
;
;								Print the ASCIIZ string at YX
;
; ************************************************************************************************

PrintMessage:
		stx 	zTemp0
		sty 	zTemp0+1
		ldy 	#0
_PMLoop:
		lda 	(zTemp0),y
		beq 	_PMExit
		phy 								; CHROUT makes no promise about Y
		jsr 	$FFD2
		ply
		iny
		bne 	_PMLoop
_PMExit:
		rts

; ************************************************************************************************
;
;							Print the ASCIIZ control line at offset X
;
; ************************************************************************************************

PrintControlLine:
_PCLLoop:
		lda 	SourceFile,x
		beq 	_PCLExit
		phx
		jsr 	$FFD2
		plx
		inx
		bra 	_PCLLoop
_PCLExit:
		rts

; ************************************************************************************************
;
;										Fixed text
;
; ************************************************************************************************


; ************************************************************************************************
;
;		IS THE SOURCE ACTUALLY A TOKENISED BASIC PROGRAM?
;
;		The compiler reads its input as tokenised BASIC: two bytes of load address, then a
;		chain of [link][line#][tokens] records. Handed anything else it does not notice. It
;		takes the first two bytes as the load address, follows whatever the next two happen to
;		be as a link pointer, and walks off through the file -- which surfaces as a hang or a
;		disk error, saying nothing at all about the real problem.
;
;		AND IT IS AN EASY FILE TO GET WRONG, because the two spellings differ by one
;		extension: DIR.BASL is BASLOAD SOURCE, plain text, and DIR.PRG is what BASLOAD makes
;		of it. Only the second one can be compiled.
;
;		The test is the load address. An X16 BASIC program starts at $0801 -- BASIC has
;		nowhere else to put one -- so the first two bytes read $01 $08 or this is not a
;		program. That is the same invariant source/gpc/build_basl.py checks on the way out
;		of BASLOAD, so the two ends of the build agree on what a program is.
;
;		A FILE THAT WILL NOT GIVE UP TWO BYTES IS A SEPARATE ANSWER. CMDR-DOS opens a file
;		that is not there quite happily and only admits it on the first read (compiler/
;		symfile.asm learned this the same way), so 'missing' and 'empty' both arrive here as
;		a read that fails immediately -- and both are worth telling apart from a file that is
;		present but is not a program.
;
;		CC = go ahead. CS = the message is already printed, do not compile.
;
; ************************************************************************************************

ValidateSourceFile:
		ldy 	#SourceFile >> 8
		ldx 	#SourceFile & $FF
		jsr 	IOOpenRead

		;
		;		BOTH BYTES ARE READ BEFORE EITHER IS COMPARED, and that ordering is the whole
		;		difference between the two messages below. IOReadByte tests ST BEFORE it reads,
		;		so on a file that is not there the FIRST call still comes back carry clear with a
		;		zero byte -- the status only appears on the second. Comparing after the first read
		;		therefore called every missing file 'not a program', which is true but unhelpful.
		;
		;		X carries the low byte across: IOReadByte saves and restores it (phx/plx).
		;
		jsr 	IOReadByte 				; low byte of the load address
		bcs 	_VSFUnreadable
		tax 						; stash it -- IOReadByte preserves X
		jsr 	IOReadByte 				; and the high byte
		bcs 	_VSFUnreadable
		cmp 	#$08
		bne 	_VSFNotProgram
		cpx 	#$01
		bne 	_VSFNotProgram
		jsr 	IOReadClose 				; $0801, so it is a program. Close it again --
		clc 						; the compiler opens the source for itself, from
		rts 						; the top (api.asm, _CAOpenIn).


_VSFUnreadable:
		jsr 	IOReadClose
		ldx 	#NoSourceText & $FF
		ldy 	#NoSourceText >> 8
		bra 	_VSFFail
_VSFNotProgram:
		jsr 	IOReadClose
		ldx 	#NotProgramText & $FF
		ldy 	#NotProgramText >> 8
_VSFFail:
		jsr 	PrintMessage
		sec
		rts

ControlFile:
		.text 	'GPC.INPUT',0
WorkingText: 								; no CR: VersionText finishes the line, so the engine's
		.text 	'GPC SQUEALING... ',0 		; own build number is the first thing it tells you
InText: 									; uppercase: the screen boots in PETSCII upper/graphics, where
		.text 	'IN:  ',0 				; lowercase bytes are graphics glyphs, not letters
OutText: 									; the CR ends the source line and starts the object's
		.text 	13,'OUT: ',0
NoControlText:
		.text 	'NO GPC.INPUT FILE',13,0
NoSourceText:
		.text 	'SOURCE NOT FOUND OR EMPTY',13,0
NotProgramText:
		.text 	'NOT A BASIC PRG FILE',13,0

; ************************************************************************************************
;
;		The three lines of GPC.INPUT, laid out as one contiguous block -- see CFLineSize above.
;
;		These are buffers, but they are deliberately NOT in the storage section. That section is
;		a .dsection at $0400 (common.inc) and the code starts at $0801, so it is a 1K hole -- and
;		it was already full. Everything here belongs to the compiler, which lives above
;		ObjectBase and is thrown away when the object code is written, so a buffer here costs a
;		compiled program nothing at all. See the note in file-io/read.asm.
;
; ************************************************************************************************

SourceFile: 								; line 1 : what to compile
		.fill 	CFLineSize
ObjectFile: 								; line 2 : where to write it
		.fill 	CFLineSize
OptionsText: 								; line 3 : the debug map file name, or empty for none
		.fill 	CFLineSize 					; (WriteMapFile keys off its first byte)
ModeText: 									; line 4 : compile mode -- first byte 'S' (SHARED) selects
		.fill 	CFLineSize 					; the resident runtime (GPC.RT.nnn.BIN); empty/anything else
											; = the default self-contained (embedded) runtime.
cfLine: 									; ReadControlFile scratch: current line, 0..3
		.fill 	1
cfJustCR: 									; ReadControlFile scratch: nonzero if the last byte was a CR
		.fill 	1

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		gpscan.asm
;		Purpose:	Decide whether the compiled program uses any GP.BASIC handler.
;		Created:	18th August 2026
;
; ************************************************************************************************
; ************************************************************************************************
;
;		The GP handlers are the last thing in the runtime image, from GPBase to ObjectBase. If
;		the program never reaches any of them the whole block can be left out of the object --
;		see WriteObjectCode. This decides which.
;
;		IT ASKS THE QUESTION BY ADDRESS, NOT BY NAME OR BY TOKEN NUMBER. For each opcode in the
;		finished p-code it asks whether that opcode's handler lives at or above GPBase. That is
;		precisely the property being relied on -- "does this instruction jump into the bytes I
;		am about to discard?" -- so it cannot drift: move a handler into or out of gp-runtime/
;		and this follows it with no list to update. A token-number range check would have needed
;		the GP opcodes renumbered contiguously (an RT_ABI bump and a forced recompile of every
;		shared-mode program), and a "keyword starts with GP." check would have been a naming
;		convention pretending to be an invariant.
;
;		IT READS A BITMAP RATHER THAN THE VECTOR TABLE, and that is the only thing that changed
;		when the runtime became a separate file. It used to do the comparison itself --
;		"lda VectorTable+1,y : cmp #GPBase >> 8" -- which needed the runtime's table resident,
;		and the runtime is on disk now. But it never wanted the address, only one bit of it, so
;		genrtimage.py does the comparison against the image's own linked table at build time and
;		emits GPUsageBits. Same question, same answer, asked of 32 bytes instead of 386.
;
;		IT SCANS THE P-CODE RATHER THAN HOOKING THE EMITTER, which is what makes it total.
;		Tokens reach the object from two places -- the generator's T action for most keywords,
;		and hand-written X: helpers for the five that carry inline branch offsets (GP.EXITDO and
;		the four GP.SELECT commands, which cannot use T at all). Hooking emission means hooking
;		both, and means the next hand-written GP command silently opts itself out of the check.
;		Reading the finished code has one site and no way to miss anything.
;
;		MoveObjectForward is what makes the walk safe: it steps by real instruction size, so an
;		operand byte that happens to equal a GP opcode is never read as one. Same reason
;		FixBranches uses it.
;
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;		Set gpUsed nonzero if the object code at FreeMemory..objPtr reaches any handler at or
;		above GPBase. Preserves objPtr.
;
; ************************************************************************************************

ScanGPUsage:
		stz 	gpUsed
		lda 	objPtr 						; the walk destroys objPtr, and WriteObjectCode still
		sta 	gpScanEnd 					; needs it as the end of the object code
		lda 	objPtr+1
		sta 	gpScanEnd+1
		.set16 	objPtr,FreeMemory
_GPSLoop:
		lda 	(objPtr) 					; the opcode
		cmp 	#$FF 						; the end marker, and it must be tested BEFORE the
		beq 	_GPSDone 					; lookup: $FF is not an opcode at all
		cmp 	#PCD_ENDSYSTEM+1 			; nothing above the last system token is a real opcode
		bcs 	_GPSNext 					; (defensive -- the walk should never produce one)
		cmp 	#PCD_STARTSYSTEM 			; the .shift prefix -- a two byte token, the one that
		beq 	_GPSShifted 				; matters is the byte after it
		cmp 	#PCD_STARTBINARY 			; below $80 is a variable or literal reference, which
		bcc 	_GPSNext 					; has no vector slot at all
		ldx 	#0 							; VectorTable half of the map
		bra 	_GPSCheck
_GPSShifted:
		ldy 	#1
		lda 	(objPtr),y 					; the shifted token
		ldx 	#1 							; ShiftVectorTable half likewise
_GPSCheck:
		jsr 	_GPSUsesGP 					; carry set if this opcode's handler is above the cut
		bcc 	_GPSNext
		lda 	#1
		sta 	gpUsed
		bra 	_GPSDone 					; one is enough -- nothing later can un-use it
_GPSNext:
		jsr 	MoveObjectForward
		bcc 	_GPSLoop
		jsr 	GPBankHop 					; a GP.BANKED region is past the GP.ASM pool, so the
		bcc 	_GPSLoop 					; walk leaves low memory and carries on there. Its
_GPSDone: 									; keywords count exactly like any other.
		lda 	gpScanEnd 					; put objPtr back
		sta 	objPtr
		lda 	gpScanEnd+1
		sta 	objPtr+1
		rts

;
;		A = token ($80..$FF), X = 0 for the plain table / 1 for the shifted one. Returns carry
;		set if that opcode's handler is at or above GPBase.
;
;		GPUsageBits is 32 bytes: 16 for the plain vectors, then 16 for the shifted, one bit per
;		opcode, bit set meaning "above the cut". The index is the token with bit 7 cleared,
;		which is exactly what the tables themselves are indexed by.
;
_GPSUsesGP:
		pha
		and 	#$7F 						; opcode index, 0..127
		lsr 	a
		lsr 	a
		lsr 	a 							; -> which byte of the map, 0..15
		cpx 	#0
		beq 	_GPSUPlain
		clc
		adc 	#16 						; the shifted half is the second 16 bytes
_GPSUPlain:
		tay
		lda 	GPUsageBits,y
		sta 	gpBits
		pla
		and 	#$07 						; -> which bit of that byte
		tax
		lda 	gpBits
_GPSUShift:
		cpx 	#0
		beq 	_GPSUTest
		lsr 	a
		dex
		bra 	_GPSUShift
_GPSUTest:
		lsr 	a 							; the wanted bit falls into the carry
		rts

gpUsed: 									; nonzero if any GP handler is reachable. Code section,
		.fill 	1 							; not storage -- it belongs to the compiler and is
gpScanEnd: 									; thrown away with it, so it costs a compiled program
		.fill 	2 							; nothing. See the note in file-io/read.asm.
gpBits:
		.fill 	1

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		30/08/26		Vector table read replaced by the generated GPUsageBits bitmap, so the
;						runtime image no longer has to be resident to answer the question.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		memreport.asm
;		Purpose:	Report what the compiled program costs and what it has left.
;		Created:	18th August 2026
;
; ************************************************************************************************
; ************************************************************************************************
;
;		One line, printed after OK:
;
;			CODE 1234 FREE 20480 RT 12031 GP-BASIC OUT
;			CODE 1234 FREE 19200 RT SHARED
;
;		CODE	the p-code, FreeMemory..objPtr. What the program IS.
;		FREE	what is left above it for variables, strings and arrays -- workspace start up to
;				$9F00 embedded, or up to RTBASE in shared mode where the resident runtime sits on
;				top. This is the number that actually runs out, and nothing printed it before:
;				PROGRAM TOO BIG was the only feedback, and it arrives only once it is too late.
;				It EXCLUDES the 4K frame stack gap, which is reserved, not available.
;		RT		the runtime bytes carried in the object, or SHARED when there are none because
;				the program loads GPC.RT.nnn.BIN instead.
;		GP-BASIC  embedded only -- OUT if the GP.BASIC handler block was dropped (gpscan.asm),
;				IN if some keyword reached it and the whole runtime had to go in. Named for the
;				language, not abbreviated to "GP": the block it is reporting on is the GP.BASIC
;				one, and the line is read by people who know the language by that name.
;
;		All three are computed here rather than stashed by WriteObjectCode: objPtr,
;		newWorkspacePage and runtimeEndPage all survive it unchanged, and WriteMapFile touches
;		none of them, so there is nothing to preserve and no second copy to fall out of step.
;
; ************************************************************************************************

		.section code

PrintMemoryReport:
		;
		;		CODE -- the p-code length.
		;
		ldx 	#CodeText & $FF
		ldy 	#CodeText >> 8
		jsr 	PrintMessage
		sec
		lda 	objPtr
		sbc 	#FreeMemory & $FF
		sta 	reportValue
		lda 	objPtr+1
		sbc 	#FreeMemory >> 8
		sta 	reportValue+1
		jsr 	PrintDecimal
		;
		;		FREE -- workspace start up to the ceiling, which differs by mode. Both ends are
		;		page numbers, so the difference is the high byte of the answer and the low byte
		;		is always zero.
		;
		ldx 	#FreeText & $FF
		ldy 	#FreeText >> 8
		jsr 	PrintMessage
		lda 	#ObjectCeiling >> 8 		; embedded: the object grows up to the I/O page
		ldx 	ModeText
		cpx 	#'S'
		bne 	_PMRCeiling
		lda 	sharedCeilPage 				; shared: whichever runtime file this program will load --
_PMRCeiling:								; RTBASE for the core only, RTGPBASE with the handlers
		sec
		sbc 	newWorkspacePage
		sta 	reportValue+1
		stz 	reportValue
		jsr 	PrintDecimal
		;
		;		RT -- embedded runtime bytes, $0801 to the cut, or SHARED.
		;
		ldx 	#RTText & $FF
		ldy 	#RTText >> 8
		jsr 	PrintMessage
		lda 	ModeText
		cmp 	#'S'
		bne 	_PMREmbedded
		ldx 	#SharedText & $FF 			; "SHARED" then which of the two files it wants
		ldy 	#SharedText >> 8
		jsr 	PrintMessage
		ldx 	#CoreText & $FF
		ldy 	#CoreText >> 8
		lda 	gpUsed
		beq 	_PMRWhich
		ldx 	#FullText & $FF
		ldy 	#FullText >> 8
_PMRWhich:
		jsr 	PrintMessage
		bra 	_PMRDone
_PMREmbedded:
		sec
		lda 	#0 							; the runtime as written: cut - RTIMG_LOAD. The label
		sbc 	#RTIMG_LOAD & $FF 			; used to be StartBasicProgram, which lives in the
		sta 	reportValue 				; runtime image and so is no longer linked here --
		lda 	runtimeEndPage 				; genrtimage.py hands the address across instead.
		sbc 	#RTIMG_LOAD >> 8
		sta 	reportValue+1
		jsr 	PrintDecimal
		;
		;		GP -- and only here, because in shared mode the handlers are in the resident
		;		runtime whatever this program does, so there is nothing to report.
		;
		ldx 	#GPOutText & $FF
		ldy 	#GPOutText >> 8
		lda 	gpUsed
		beq 	_PMRGP
		ldx 	#GPInText & $FF
		ldy 	#GPInText >> 8
_PMRGP:
		jsr 	PrintMessage
_PMRDone:
		lda 	#13
		jmp 	$FFD2

; ************************************************************************************************
;
;		reportValue (16 bit) to the screen as decimal, leading zeros suppressed but always at
;		least one digit. Subtract each power of ten as many times as it goes; the count is the
;		digit. Same method as _WMFDecimal, which writes to the map FILE through IOWriteByte --
;		this one goes to CHROUT. They are kept apart rather than sharing an indirect output
;		vector: two tiny routines are easier to be sure of than one with a mode.
;
; ************************************************************************************************

PrintDecimal:
		stz 	reportLead 					; 0 while we are still dropping leading zeros
		ldx 	#0
_PDPow:
		ldy 	#48 						; '0' + number of subtractions = the digit
_PDSub:
		sec
		lda 	reportValue
		sbc 	_PDPow10L,x
		sta 	reportTemp
		lda 	reportValue+1
		sbc 	_PDPow10H,x
		bcc 	_PDUnder 					; borrow -> this power no longer goes
		sta 	reportValue+1
		lda 	reportTemp
		sta 	reportValue
		iny
		bra 	_PDSub
_PDUnder:
		cpy 	#48 						; a zero digit ...
		bne 	_PDEmit
		lda 	reportLead 					; ... is dropped while still leading
		beq 	_PDNext
_PDEmit:
		lda 	#1
		sta 	reportLead
		phx
		tya
		jsr 	$FFD2 						; CHROUT makes no promise about X
		plx
_PDNext:
		inx
		cpx 	#4 							; 10000, 1000, 100, 10
		bne 	_PDPow
		lda 	reportValue 				; the units digit is always written
		ora 	#48
		jmp 	$FFD2

_PDPow10L:
		.byte 	<10000, <1000, <100, <10
_PDPow10H:
		.byte 	>10000, >1000, >100, >10

;
;		Uppercase throughout: the X16 boots in PETSCII upper/graphics, where lowercase bytes
;		come out as graphics glyphs. Same reason bumpbuild.py emits 'V' not 'v'.
;
CodeText:
		.text 	"CODE ",0
FreeText:
		.text 	" FREE ",0
RTText:
		.text 	" RT ",0
SharedText:
		.text 	"SHARED",0
CoreText: 									; which resident runtime file this program will ask for
		.text 	" RC",0 					; GPC.RC.nnn.BIN -- core only, no GPB handlers
FullText:
		.text 	" RT",0 					; GPC.RT.nnn.BIN -- handlers and core
GPOutText:
		.text 	" GP-BASIC OUT",0
GPInText:
		.text 	" GP-BASIC IN",0

reportValue: 								; code section, not storage -- these belong to the
		.fill 	2 							; compiler and are thrown away when the object is
reportTemp: 								; written, so they cost a compiled program nothing.
		.fill 	2 							; See the note in file-io/read.asm.
reportLead:
		.fill 	1

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		object.asm
;		Purpose:	Write object code out.
;		Created:	9th October 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;									Write object code out.
;
; ************************************************************************************************

;
;		FrameStackPages -- the gap left below the workspace for the runtime (GOSUB/FOR) stack --
;		was defined here. It now lives in common-source/source/common.inc, because the runtime
;		needs the same number to know where the bottom of that gap is (StackOpenFrame).
;

; ************************************************************************************************
;
;		Write object code out.
;
;		In memory the layout is
;
;			$0801 [ runtime ] ObjectBase [ compiler ] FreeMemory [ object code ] objPtr
;
;		but a saved program never compiles anything, so the compiler is dead weight. The
;		file is therefore written in two pieces -- the runtime, then the object code -- so
;		that on reload the object code lands at ObjectBase, on top of where the compiler was.
;
;		That reclaims (FreeMemory-ObjectBase) bytes from every compiled program, and, more
;		importantly, lets the workspace start just above the object code instead of at a
;		hardcoded $8000 -- which is most of the useable memory a compiled program gets.
;
;		The two immediates in StartCode are patched as they stream past, rather than in RAM,
;		so the copy still in memory (RUN a second time) keeps running from FreeMemory.
;
; ************************************************************************************************

WriteObjectCode:
		lda 	ModeText 					; GPC.INPUT line 4 -- 'S' (SHARED) selects resident-runtime
		cmp 	#'S' 						; mode: emit a bootstrap + p-code, no embedded runtime
		bne 	_WOCEmbedded 				; (see the shared branch below and compiler/bootstrap.asm).
		jmp 	_WOCShared 					; jmp, not a branch -- the embedded path is >127 bytes
_WOCEmbedded:
		jsr 	ScanGPUsage 				; does anything reach a handler above GPBase ?
		;
		;		The cut. A program using no GP.BASIC keyword takes the runtime as $0801..GPBase
		;		and puts its object code there; one that uses any takes the whole thing,
		;		$0801..ObjectBase, exactly as before. Both labels are page aligned, so a single
		;		page number says which -- and it is used THREE times below (the copy terminator,
		;		the RunCodePage patch and the workspace base), so it is settled once, here.
		;
		lda 	#GPBase >> 8
		ldx 	gpUsed
		beq 	_WOCCutSet
		lda 	#ObjectBase >> 8
_WOCCutSet:
		sta 	runtimeEndPage
		;
		;		zTemp1 = length of the object code.
		;
		sec
		lda 	objPtr
		sbc 	#FreeMemory & $FF
		sta 	zTemp1
		lda 	objPtr+1
		sbc 	#FreeMemory >> 8
		sta 	zTemp1+1
		;
		;		Round that up to whole pages.
		;
		lda 	zTemp1 						; any part page ?
		beq 	_WOCWholePages
		inc 	zTemp1+1 					; then it needs one more
_WOCWholePages:
		;
		;		newWorkspacePage = ObjectBase + pages(object code) + the frame stack gap.
		;
		;		...and then check the program can actually RUN, which the embedded path never
		;		did -- only the SHARED path had the equivalent test. That was survivable while
		;		the compiler itself capped p-code at 12,032 bytes; with the object buffer now
		;		reaching $9EFF it is not, because a program can be compiled successfully and
		;		still leave no room above itself for variables, arrays and strings. It would
		;		load, start, and then fail in some unrelated-looking way at run time.
		;
		;		The workspace runs from newWorkspacePage to $9F00, so require MIN_WS_PAGES (4K)
		;		of it, and reject a page count that overflowed a byte on the way -- the same two
		;		tests, in the same order, as _WOCShared.
		;
		clc
		lda 	runtimeEndPage 				; where the object code will actually land
		adc 	zTemp1+1
		bcs 	_WOCTooBig
		adc 	#FrameStackPages
		bcs 	_WOCTooBig
		sta 	newWorkspacePage
		cmp 	#(ObjectCeiling >> 8) - MIN_WS_PAGES + 1
		bcc 	_WOCFits
_WOCTooBig:
		jmp 	_WOCSBig 					; shared with the SHARED path: prints PROGRAM TOO BIG,
_WOCFits: 									; returns carry set, caller skips the map file and OK

		jsr 	PatchAsmFixups 				; GP.ASM: blob calls, label targets and {VAR}, all of
											; which needed newWorkspacePage as well as the run base

		;
		;		THE RUNTIME IMAGE IS OPENED FIRST, before the object file is created. It is the
		;		one thing here that can fail for a reason outside this program, and a compile
		;		that dies after creating OBJECT.PRG leaves a truncated file that looks like a
		;		program. IODeleteOutputs has already removed the old one, so failing here leaves
		;		no object at all -- the only state that cannot be mistaken for a good one.
		;
		ldx 	#RTImageFileText & $FF
		ldy 	#RTImageFileText >> 8
		jsr 	IOOpenImage
		bcc 	_WOCImgOpened
		;
		;		Both failure paths are at the far end of this file, out of branch range from
		;		here -- the same trampoline _WOCSBigFar needs, for the same reason.
		;
_WOCImgNoneFar:
		jmp 	_WOCNoImage
_WOCImgBadFar:
		jmp 	_WOCBadImage
_WOCImgOpened:
		jsr 	IOImageIn
		jsr 	IOReadByte 					; the image's own two byte load address, which is
		bcs 	_WOCImgBadFar 				; not part of the runtime and must not be copied
		cmp 	#RTIMG_LOAD & $FF
		bne 	_WOCImgBadFar
		jsr 	IOReadByte
		bcs 	_WOCImgBadFar
		cmp 	#RTIMG_LOAD >> 8
		bne 	_WOCImgBadFar

		ldy 	#ObjectFile >> 8
		ldx 	#ObjectFile & $FF
		jsr 	IOOpenWrite 				; open write

		lda 	#RTIMG_LOAD & $FF 			; write out the load address $0801
		jsr 	IOWriteByte
		lda 	#RTIMG_LOAD >> 8
		jsr 	IOWriteByte
		;
		;		Part one : the runtime, $0801 up to the cut, streamed from GPC.IMG.nnn.BIN and
		;		patched as it goes past. A PAGE AT A TIME, not a byte at a time: both files are
		;		open together and the KERNAL has one input channel and one output channel, so
		;		every switch between them is a CHKIN/CHKOUT pair. Per byte that is 28,000 of
		;		them; per page it is 94.
		;
		;		imgCount is the size of the chunk in hand, with ZERO MEANING 256 -- which is
		;		what makes "cpy imgCount / bne" run a full page when the counter wraps back to
		;		its start. Only the last chunk is ever short.
		;
		sec 								; imgLeft = (runtimeEndPage:00) - RTIMG_LOAD
		lda 	#0
		sbc 	#RTIMG_LOAD & $FF
		sta 	imgLeft
		lda 	runtimeEndPage
		sbc 	#RTIMG_LOAD >> 8
		sta 	imgLeft+1
		stz 	imgPage
_WOCImgChunk:
		lda 	#0 							; a whole page, unless less than one is left
		ldx 	imgLeft+1
		bne 	_WOCImgHaveN
		lda 	imgLeft
_WOCImgHaveN:
		sta 	imgCount

		jsr 	IOImageIn 					; read the chunk in
		ldy 	#0
_WOCImgRead:
		jsr 	IOReadByte
		bcs 	_WOCImgBadFar 				; the image is shorter than ObjectBase says
		sta 	imageBuffer,y
		iny
		cpy 	imgCount
		bne 	_WOCImgRead
		;
		;		The two immediates. Chunks start on page boundaries of the STREAM (the load
		;		address was consumed before the first one), so "is this offset in this chunk"
		;		is a page compare and the offset within it is the low byte. Both live in the
		;		first page in practice; the test does not assume it.
		;
		lda 	imgPage
		cmp 	#RTIMG_CODEPOFS >> 8
		bne 	_WOCImgNoCode
		ldy 	#RTIMG_CODEPOFS & $FF
		lda 	runtimeEndPage 				; object code moves down to here
		sta 	imageBuffer,y
_WOCImgNoCode:
		lda 	imgPage
		cmp 	#RTIMG_WSPAGEOFS >> 8
		bne 	_WOCImgNoWS
		ldy 	#RTIMG_WSPAGEOFS & $FF
		lda 	newWorkspacePage 			; so the workspace can start much lower
		sta 	imageBuffer,y
_WOCImgNoWS:
		jsr 	IOObjectOut 				; and write it out
		ldy 	#0
_WOCImgWrite:
		lda 	imageBuffer,y
		jsr 	IOWriteByte
		iny
		cpy 	imgCount
		bne 	_WOCImgWrite

		inc 	imgPage
		lda 	imgCount 					; imgLeft -= imgCount, remembering the zero
		bne 	_WOCImgSubN
		dec 	imgLeft+1 					; a whole page
		bra 	_WOCImgMore
_WOCImgSubN:
		sec
		lda 	imgLeft
		sbc 	imgCount
		sta 	imgLeft
		bcs 	_WOCImgMore
		dec 	imgLeft+1
_WOCImgMore:
		lda 	imgLeft
		ora 	imgLeft+1
		bne 	_WOCImgChunk

		jsr 	IOCloseImage 				; CLRCHNs, so the object file has to be reselected
		jsr 	IOObjectOut
		;
		;		Part two : the object code itself, which lands at ObjectBase on reload.
		;
		.set16 	zTemp0,FreeMemory
_WOCCode:
		lda 	zTemp0 						; done ?
		cmp 	objPtr
		bne 	_WOCCodeByte
		lda 	zTemp0+1
		cmp 	objPtr+1
		beq 	_WOCDone
_WOCCodeByte:
		lda 	(zTemp0)
		jsr 	IOWriteByte
		inc 	zTemp0
		bne 	_WOCCode
		inc 	zTemp0+1
		bra 	_WOCCode
_WOCDone:
		jsr 	IOWriteClose 				; close the file.
		clc 								; success -- CompileCode reads the carry (set = rejected)
		rts

; ************************************************************************************************
;
;		Shared (resident-runtime) output: [$0801 bootstrap][$0900 p-code], no embedded runtime.
;		The bootstrap (compiler/bootstrap.asm) is streamed as the first 255 bytes with WS_START
;		patched in; the p-code follows and lands at $0900 on reload. A program whose p-code +
;		frame-stack gap + minimum workspace would not fit below RTBASE is rejected (carry set).
;
; ************************************************************************************************

_WOCShared:
		;
		;		p-code length -> whole pages (same as the embedded path)
		;
		;		...but only the LOW part of it. A GP.BANKED region sits at the top of the object,
		;		page aligned, and the bootstrap moves it into the bank before the runtime starts.
		;		So the workspace begins where the region begins: those bytes are in the file, and
		;		in memory for as long as it takes to copy them, and then they are workspace. That
		;		is the whole return on putting the region up there.
		;
		lda 	objPtr
		ldy 	objPtr+1
		ldx 	gpBankActive
		beq 	_WOCSLength
		lda 	gpBankStart 				; where the region ends up -- page aligned
		ldy 	gpBankStart+1
_WOCSLength:
		sec
		sbc 	#FreeMemory & $FF
		sta 	zTemp1
		tya
		sbc 	#FreeMemory >> 8
		sta 	zTemp1+1
		lda 	zTemp1
		beq 	_WOCSWhole
		inc 	zTemp1+1
_WOCSWhole:
		;
		;		WS_START = PCODE_PAGE + pages(p-code) + the frame-stack gap. Reject if that leaves
		;		fewer than MIN_WS_PAGES below RTBASE, or if the page count itself overflowed a byte.
		;
		jsr 	ScanGPUsage 				; the shared runtime is two files now -- see below
		;
		;		The workspace ends where the resident runtime starts, and that is no longer one
		;		address: a program using no GPB keyword loads the CORE-ONLY file at RTBASE and keeps
		;		everything below it, one using GPB loads the full file at RTGPBASE and stops there.
		;		2,560 bytes between them, so it is worth knowing which.
		;
		lda 	#RTBASE >> 8
		ldx 	gpUsed
		beq 	_WOCSCeiling
		lda 	#RTGPBASE >> 8
_WOCSCeiling:
		sta 	sharedCeilPage
		clc
		lda 	#PCODE_PAGE
		adc 	zTemp1+1
		bcs 	_WOCSBigFar
		adc 	#FrameStackPages
		bcs 	_WOCSBigFar
		sta 	newWorkspacePage 			; reuse this byte to carry WS_START
		;
		;		Reject unless MIN_WS_PAGES still fit below the ceiling. Computed as a THRESHOLD and
		;		compared, rather than subtracting the ceiling from the start page: the subtraction
		;		underflows when the p-code has already run past the ceiling, and an underflow reads as
		;		a small positive gap -- i.e. it accepts exactly the programs it exists to reject.
		;
		lda 	sharedCeilPage
		sec
		sbc 	#MIN_WS_PAGES - 1 			; the highest start page that still leaves a workspace
		sta 	zTemp1 						; (the low byte is spent -- only zTemp1+1 is still live)
		lda 	newWorkspacePage
		cmp 	zTemp1
		bcs 	_WOCSBigFar
		bra 	_WOCSFits
;
;		_WOCSBig is at the far end of this file, out of branch range from here -- the same
;		trampoline FixBranches needs for its GP.EXITDO handler, for the same reason.
;
_WOCSBigFar:
		jmp 	_WOCSBig
_WOCSFits:
		jsr 	PatchAsmFixupsShared 		; GP.ASM, as the embedded path -- see _WOCFits
		;
		;		Header: a normal PRG loading at $0801 -- the bootstrap sits there.
		;
		ldy 	#ObjectFile >> 8
		ldx 	#ObjectFile & $FF
		jsr 	IOOpenWrite
		lda 	#1
		jsr 	IOWriteByte
		lda 	#8
		jsr 	IOWriteByte
		;
		;		Part one: the bootstrap, ProgramBootstrap..ProgramBootstrapEnd, patching three operand
		;		bytes as they stream past. Build the table first -- the addresses are constants but all
		;		three VALUES are per-program, so it cannot be static data.
		;
		.set16 	BootPatchTable, ProgramBootstrap+BootWSPatchOffset
		lda 	newWorkspacePage 			; where this program's workspace starts
		sta 	BootPatchTable+2
		.set16 	BootPatchTable+3, ProgramBootstrap+BootWSEndPatchOffset
		lda 	sharedCeilPage 				; ... and where it ends: RTBASE or RTGPBASE
		sta 	BootPatchTable+5
		.set16 	BootPatchTable+6, ProgramBootstrap+BootGPPatchOffset
		lda 	gpUsed 						; ... and whether the handlers have to come with it
		beq 	_WOCSFlag
		lda 	#1 							; normalise: the bootstrap tests it with BEQ
_WOCSFlag:
		sta 	BootPatchTable+8
		;
		;		...and the three GP.BANKED needs: where the region sits once the program is
		;		loaded, how many pages of it there are, and which bank it belongs in. All three
		;		are zero for a program with no region, and a zero page count is what makes the
		;		bootstrap skip the copy entirely.
		;
		.set16 	BootPatchTable+9, ProgramBootstrap+BootCodeSrcOffset
		lda 	gpBankRunBase 				; an instruction OPERAND, not a data byte
		sta 	BootPatchTable+11
		.set16 	BootPatchTable+12, ProgramBootstrap+BootCodePagesOffset
		lda 	gpBankPages
		sta 	BootPatchTable+14
		.set16 	BootPatchTable+15, ProgramBootstrap+BootCodeBankOffset
		lda 	gpBankNumber
		sta 	BootPatchTable+17
		.set16 	zTemp0,ProgramBootstrap
_WOCSBoot:
		;
		;		SIX patched bytes now, not one, so the loop asks a table rather than growing a sixth
		;		copy of the same compare. Each entry is (address lo, hi, value): workspace START page,
		;		workspace END page -- which is the runtime base this program will use -- the flag
		;		saying whether it needs the GPB handlers at all, and then GP.BANKED's three.
		;
		ldx 	#0
_WOCSBootPatch:
		lda 	zTemp0
		cmp 	BootPatchTable,x
		bne 	_WOCSBootNext
		lda 	zTemp0+1
		cmp 	BootPatchTable+1,x
		bne 	_WOCSBootNext
		lda 	BootPatchTable+2,x 			; the byte to substitute
		bra 	_WOCSBootEmit
_WOCSBootNext:
		inx
		inx
		inx
		cpx 	#BootPatchEnd-BootPatchTable
		bne 	_WOCSBootPatch
		lda 	(zTemp0)
_WOCSBootEmit:
		jsr 	IOWriteByte
		inc 	zTemp0
		bne 	_WOCSBootNoHi
		inc 	zTemp0+1
_WOCSBootNoHi:
		lda 	zTemp0
		cmp 	#<ProgramBootstrapEnd
		bne 	_WOCSBoot
		lda 	zTemp0+1
		cmp 	#>ProgramBootstrapEnd
		bne 	_WOCSBoot
		;
		;		Part two: the p-code from FreeMemory..objPtr, which lands at $0900 on reload.
		;
		.set16 	zTemp0,FreeMemory
_WOCSCode:
		lda 	zTemp0
		cmp 	objPtr
		bne 	_WOCSCodeByte
		lda 	zTemp0+1
		cmp 	objPtr+1
		beq 	_WOCSCodeDone
_WOCSCodeByte:
		lda 	(zTemp0)
		jsr 	IOWriteByte
		inc 	zTemp0
		bne 	_WOCSCode
		inc 	zTemp0+1
		bra 	_WOCSCode
_WOCSCodeDone:
		jsr 	IOWriteClose
		clc 								; success
		rts
_WOCSBig:
		ldx 	#ProgramTooBigText & $FF
		ldy 	#ProgramTooBigText >> 8
		bra 	_WOCFail

;
;		The runtime image is missing, or is not the file its name claims. Either way there is
;		no object: the image is opened before OBJECT.PRG is created precisely so that this
;		leaves nothing behind. The name carries the runtime build number, so "missing" is also
;		what a stale image from an older release looks like -- which is the point of numbering
;		it rather than trusting a fixed name to be the right one.
;
_WOCBadImage: 								; missing, wrong load address, or shorter than
_WOCNoImage: 								; ObjectBase says it should be
		jsr 	IOCloseImage 				; CLOSE on a logical file that was never opened is
											; harmless, and the OPEN may have half-registered it.
											; Leaving it would fail the NEXT compile's open, and
											; re-RUNning the compiler is now the only way to
											; retry -- PatchOutCompile used to make a second RUN
											; run the program instead.
		ldx 	#NoRuntimeImageText & $FF
		ldy 	#NoRuntimeImageText >> 8
_WOCFail:
		jsr 	PrintMessage
		sec 								; rejected -- CompileCode skips the map file and the OK
		rts

ProgramTooBigText:
		.text 	"PROGRAM TOO BIG", 13, 0

NoRuntimeImageText:
		.text 	"NO RUNTIME IMAGE", 13, 0

; ************************************************************************************************
;
;		Write the debug MAP file, if GPC.INPUT gave a third line (its name). The map turns a
;		runtime error's "@ $XXXX" back into a source line, which is otherwise a hand decode of
;		the p-code. One text line per source line, in ascending code order:
;
;			0030 12
;
;		the 4-digit hex P-CODE OFFSET -- exactly what the runtime prints as "@ $0030" -- then a
;		space and the DECIMAL BASIC line number that begins there. To place an error, find the
;		largest offset that is <= the one reported.
;
;		ASCENDING CODE ORDER, EXCEPT AFTER A GP.BANKED. The table is walked in the order the
;		lines were marked, which is source order, and those two were the same thing until
;		GPBankRelocate started lifting a region out to the end of the object. A program with a
;		region in it has that region's lines carrying the HIGHEST offsets while still sitting
;		where they were written. Every entry is still right; the file is simply no longer
;		sorted, so the "largest offset <= the one reported" rule means reading the whole file
;		rather than reading down it. Sorting here instead would cost a sort of a 2,048 entry
;		banked table, and the reader can sort.
;
;		It is built straight from the compiler's line-number table (STRMarkLine): 4-byte entries
;		[line# lo, line# hi, addr lo, addr hi], growing DOWNWARD from compilerEndHigh:$00 to
;		lineNumberTable, walked here from the top down. The
;		stored addr is the compile-time position in the object buffer (based at FreeMemory), so
;		offset = addr - FreeMemory -- the same number the runtime reports, because the object is
;		copied verbatim from FreeMemory to its run address. The two synthetic lines the implicit
;		-DIM prologue adds show up as line 65024 ($FE00, the end marker) and 65535 ($FFFF, the
;		prologue); they are real code positions, just not the user's.
;
; ************************************************************************************************

WriteMapFile:
		lda 	OptionsText 				; no third line -> no map asked for.
		bne 	_WMFStart
		rts
_WMFStart:
		ldy 	#OptionsText >> 8 			; open the map file for write (logical file 3, as the
		ldx 	#OptionsText & $FF 			; object write already closed).
		jsr 	IOOpenWrite
		lda 	compilerEndHigh 			; walk from the top of the table ...
		sta 	mapWalk+1
		stz 	mapWalk
_WMFLoop:
		sec 								; ... down one 4-byte entry at a time.
		lda 	mapWalk
		sbc 	#4
		sta 	mapWalk
		lda 	mapWalk+1
		sbc 	#0
		sta 	mapWalk+1
		lda 	mapWalk+1 					; stop once below the last (lowest) entry.
		cmp 	lineNumberTable+1
		bcc 	_WMFDone
		bne 	_WMFEntry
		lda 	mapWalk
		cmp 	lineNumberTable
		bcc 	_WMFDone
_WMFEntry:
		jsr 	_WMFWriteEntry
		bra 	_WMFLoop
_WMFDone:
		jmp 	IOWriteClose

;
;		Write one entry: "<hhhh> <ddddd>",CR. Everything the line needs is pulled out through
;		zTemp0 up front, before any IOWriteByte -- CHROUT to a file is free to trash zero page,
;		but mapValue/mapOff are plain RAM and survive it.
;
_WMFWriteEntry:
		lda 	mapWalk 					; point zTemp0 at the entry.
		sta 	zTemp0
		lda 	mapWalk+1
		sta 	zTemp0+1
		;
		;		The table is in banked RAM now, so page it in for the four reads and page it back
		;		out again before any file I/O -- the KERNAL owns bank 0. That the entry is fully
		;		unpacked into mapValue/mapOff before the first IOWriteByte was already true (see
		;		the note above); it is now load-bearing rather than merely tidy.
		;
		.storage_access
		ldy 	#0 							; line number -> mapValue (consumed by the decimal print)
		lda 	(zTemp0),y
		sta 	mapValue
		ldy 	#1
		lda 	(zTemp0),y
		sta 	mapValue+1
		ldy 	#2 							; offset = stored address - FreeMemory (page aligned)
		lda 	(zTemp0),y
		sec
		sbc 	#FreeMemory & $FF
		sta 	mapOff
		ldy 	#3
		lda 	(zTemp0),y
		sbc 	#FreeMemory >> 8
		sta 	mapOff+1
		.storage_release
		lda 	mapOff+1 					; hex offset, high byte then low.
		jsr 	_WMFHexByte
		lda 	mapOff
		jsr 	_WMFHexByte
		lda 	#' '
		jsr 	IOWriteByte
		jsr 	_WMFDecimal 				; decimal line number.
		lda 	#10 						; LF ends the line -- this file is read on the host (grep,
		jmp 	IOWriteByte 				; VS Code), not the X16, so a Unix newline suits it best.

;
;		A (0..255) as two hex digits. Same trick as the runtime error handler.
;
_WMFHexByte:
		pha
		lsr 	a
		lsr 	a
		lsr 	a
		lsr 	a
		jsr 	_WMFNibble
		pla
_WMFNibble:
		and 	#15
		cmp 	#10
		bcc 	_WMFDigit
		adc 	#6 							; carry set here: 10 -> +6+1 = 'A'
_WMFDigit:
		adc 	#48
		jmp 	IOWriteByte

;
;		mapValue (16 bit) as decimal, leading zeros suppressed but always at least one digit.
;		Subtract each power of ten as many times as it goes; the count is the digit.
;
_WMFDecimal:
		stz 	mapLead 					; 0 while we are still dropping leading zeros
		ldx 	#0
_WMFDPow:
		ldy 	#48 						; '0' + number of subtractions = the digit
_WMFDSub:
		sec
		lda 	mapValue
		sbc 	_WMFPow10L,x
		sta 	mapTemp
		lda 	mapValue+1
		sbc 	_WMFPow10H,x
		bcc 	_WMFDUnder 					; borrow -> this power no longer goes
		sta 	mapValue+1
		lda 	mapTemp
		sta 	mapValue
		iny
		bra 	_WMFDSub
_WMFDUnder:
		cpy 	#48 						; a zero digit ...
		bne 	_WMFDEmit
		lda 	mapLead 					; ... is dropped while still leading
		beq 	_WMFDNext
_WMFDEmit:
		lda 	#1
		sta 	mapLead
		tya
		jsr 	IOWriteByte
_WMFDNext:
		inx
		cpx 	#4 							; 10000, 1000, 100, 10
		bne 	_WMFDPow
		lda 	mapValue 					; the units digit is always written
		ora 	#48
		jmp 	IOWriteByte

_WMFPow10L:
		.byte 	<10000, <1000, <100, <10
_WMFPow10H:
		.byte 	>10000, >1000, >100, >10

BootPatchTable: 							; six (addr lo, addr hi, value) triples, built per program
		.fill 	18 							; by the shared path just above -- see the note there.
BootPatchEnd:
sharedCeilPage: 							; page the shared workspace stops at: RTBASE normally,
		.fill 	1 							; RTGPBASE when the GPB handlers sit below it.
runtimeEndPage: 							; first page ABOVE the runtime as written out: GPBase if the
		.fill 	1 							; GP block was dropped, ObjectBase if it was kept.
imgLeft: 									; bytes of the runtime image still to copy, and which
		.fill 	2 							; page of the stream the chunk in hand came from --
imgPage: 									; the patch test is a page compare, see part one.
		.fill 	1
imgCount: 									; size of the chunk in hand, ZERO MEANING 256.
		.fill 	1
newWorkspacePage: 							; first page of workspace in the saved file. In the code
		.fill 	1 							; section, not storage -- see the note in
											; file-io/read.asm.
mapWalk: 									; these too live in the code section, not storage -- they
		.fill 	2 							; belong to the compiler and are thrown away when the
mapValue: 									; object is written, so they cost a compiled program
		.fill 	2 							; nothing. See the note in file-io/read.asm.
mapOff:
		.fill 	2
mapTemp:
		.fill 	2
mapLead:
		.fill 	1

; ************************************************************************************************
;
;		GP.ASM's fixups need BOTH bases, and neither is settled until the two paths above have
;		got this far: where the object will RUN, and where the workspace will start. Patching
;		this late is free -- nothing here changes the object's length, and the buffer is not
;		streamed out until below.
;
;		FreeMemory and newWorkspacePage are application symbols and the assembler lives in the
;		compiler library, which also builds on its own, so the arithmetic has to happen on this
;		side of the line. Both ends are page aligned, so a byte each says all of it.
;
; ************************************************************************************************

PatchAsmFixups:
		sec 								; embedded: it runs at runtimeEndPage, it sits at
		lda 	runtimeEndPage 				; FreeMemory, and the difference is what every blob
		sbc 	#FreeMemory >> 8 			; address and label target has to move by
		sta 	AsmPageDelta
		lda 	newWorkspacePage
		sta 	AsmWorkspacePage
		jmp 	AsmPatchAll

PatchAsmFixupsShared:
		lda 	#(PCODE_PAGE - (FreeMemory >> 8)) & $FF
		sta 	AsmPageDelta 				; shared p-code always lands at $0900
		lda 	newWorkspacePage 			; _WOCShared carries WS_START in this byte
		sta 	AsmWorkspacePage
		jmp 	AsmPatchAll

;
;		One page of the runtime image, in transit from GPC.IMG.nnn.BIN to OBJECT.PRG. It is in
;		the code section, so it is compiler space and costs a compiled program nothing -- and
;		it buys back 9,818 bytes of low RAM that used to hold the whole image, so it is the
;		cheapest 256 bytes in the build.
;
imageBuffer:
		.fill 	256

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		read.asm
;		Purpose:	Read file code.
;		Created:	9th October 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;								 Open sequential file for Read
; 									   YX = ASCIIZ name
;
; ************************************************************************************************

IOOpenRead:
		lda 	#'R' 						; read.
		jsr 	IOSetFileName 				; set up name/LFS
		ldx	 	#3 							; use file 3 for reading
		jsr 	$FFC6 						; CHKIN
		rts

; ************************************************************************************************
;
;			 Open the runtime image for read -- YX = ASCIIZ name, carry set if it failed
;
;		ON ITS OWN LOGICAL FILE, because it is read while OBJECT.PRG is open for write and
;		everything else here uses file 3 for both. The channel is NOT selected here: the
;		streamer alternates CHKIN/CHKOUT a page at a time, so whichever it set would be wrong
;		by the time the first byte moved.
;
; ************************************************************************************************

IO_IMAGE_FILE = 4

IOOpenImage:
		lda 	#IO_IMAGE_FILE
		sta 	ioFileNo
		lda 	#'R'
		jsr 	IOSetFileName 				; carry comes back from OPEN
		ldy 	#3 							; put the default back for every other caller
		sty 	ioFileNo 					; (sty leaves the carry alone)
		rts

; ************************************************************************************************
;
;						Select the image for input / the object file for output
;
; ************************************************************************************************

IOImageIn:
		ldx 	#IO_IMAGE_FILE
		jmp 	$FFC6 						; CHKIN

IOObjectOut:
		ldx 	#3
		jmp 	$FFC9 						; CHKOUT

; ************************************************************************************************
;
;									  Close the runtime image
;
; ************************************************************************************************

IOCloseImage:
		lda 	#IO_IMAGE_FILE
		jsr 	$FFC3 						; CLOSE
		jmp 	$FFCC 						; CLRCHN -- the object file stays OPEN but stops being
											; the selected output, so IOObjectOut before writing.

; ************************************************************************************************
;
;									Read A from input file
;
;			    If read,  A=Byte and Carry Clear, else A = Error and Carry Set
;
; ************************************************************************************************

IOReadByte:
		phx 					
		phy
		jsr 	$FFB7 						; read ST
		sec
		bne 	_IORExit
		jsr 	$FFCF 						; read a byte
		clc 								; status OK.
_IORExit:		
		ply
		plx
		rts

; ************************************************************************************************
;
;							    Close files (use the same code)
;
; ************************************************************************************************

IOReadClose:
IOWriteClose:
		lda 	#3 							; CLOSE# 3
		jsr 	$FFC3
		jsr 	$FFCC 						; CLRCHN
		rts

; ************************************************************************************************
;
;				 Set LFS, Name and Open File. YX = Filename (ASCIIZ) A = R/W
;
; ************************************************************************************************

IOSetFileName:
		pha 								; save R/W
		stx 	zTemp0
		sty 	zTemp0+1
		ldy 	#$FF 						; copy name given
_IOSCopy:
		iny 								; pre-increment copy
		lda 	(zTemp0),y
		sta 	IONameBuffer,y
		bne 	_IOSCopy
		;
		pla 								; recover R/W
		cmp 	#'W'
		bne 	_IOSRead 					; reading uses the PLAIN name -- see the note below
		lda 	#',' 						; writing appends ",S,W" to create the file
		sta 	IONameBuffer+0,y
		sta 	IONameBuffer+2,y
		lda 	#'S'
		sta 	IONameBuffer+1,y
		lda 	#'W'
		sta 	IONameBuffer+3,y
		lda 	#0 							; terminator after the suffix
		sta 	IONameBuffer+4,y
		tya 								; name length plus the four we appended
		clc
		adc 	#4
		bra 	_IOSSetName
_IOSRead:
		tya 								; READ: the length is just the name -- NO ",S,R". Box16's
											; -hypercall_path opens the raw SETNAM string, so a
											; ",S,R" suffix makes it hunt for a host file literally
											; called "NAME,S,R" and the open fails. A plain name
											; reads on x16emu, Box16 and real CMDR-DOS alike (x16emu
											; only tolerated the suffix by parsing it off first).
											; Writing still needs ",S,W", which Box16 does honour.
_IOSSetName:
 								
		ldx 	#IONameBuffer & $FF			; name address to YX
		ldy 	#IONameBuffer >> 8

	    jsr 	$FFBD          				; call SETNAM

    	lda 	ioFileNo 					; set LFS to n,8,n -- n is 3 for everything except
		ldx 	#8 							; the runtime image, which has to be open for READ at
		ldy 	ioFileNo 					; the same time the object file is open for WRITE.
		jsr 	$FFBA		

		jsr 	$FFC0 						; OPEN
		rts

; ************************************************************************************************
;
;		The name, with ",S,R" or ",S,W" appended.
;
;		This was 64 bytes in the storage section, and that was a loaded gun. storage is a
;		.dsection at $0400 with the code starting at $0801 (common.inc), so it is a 1K hole --
;		and it was already full to the last byte. IONameBuffer sat at $07F1, which left it room
;		for exactly "SOURCE.PRG,S,R" and its terminator: fifteen bytes, ending at $07FF. Any
;		name longer than that would have written straight over the BASIC stub at $0801 and
;		destroyed the program that was running.
;
;		Nobody noticed because the two names were hardcoded and both were ten characters. Now
;		that GPC.INPUT supplies them, they can be any length, so the buffer is here in the code
;		section instead -- which is the compiler, above ObjectBase, thrown away when the object
;		code is written. It costs a compiled program nothing.
;
; ************************************************************************************************

ioFileNo: 									; the logical file IOSetFileName opens on. Code
		.byte 	3 							; section, like everything else here -- it is the
											; compiler's, and the compiler is thrown away.

IONameBuffer:
		.fill 	CFLineSize+8 				; the longest line GPC.INPUT can hold, plus ",S,R"
											; and the zero
		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		start.asm
;		Purpose:	Start actual compilation.
;		Created:	9th October 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;									Compile the code from disk
;
; ************************************************************************************************

CompileCode:
		jsr 	ReadControlFile 			; GPC.INPUT says what to compile and where to put it
		bcs 	_CCNoControlFile 			; and without it there is nothing to be done
		jsr 	PrintWorking 				; which is all the compiler now says for itself
		jsr 	IODeleteOutputs 			; and clear the object AND map from a PREVIOUS run, so a
								; compile that stops on an error leaves nothing behind
		jsr 	ValidateSourceFile 			; and REFUSE ANYTHING THAT IS NOT A TOKENISED PRG.
		bcs 	_CCStopped 				; AFTER the delete, so a refused compile leaves nothing
								; behind either, and after PrintWorking, so the message
								; lands under the IN:/OUT: lines that name the file.
								; It has already said which of the two reasons it was.

		;
		;		GP.BANKED needs to know where the p-code will RUN, and it needs it INSIDE the
		;		compile: FixBranches resolves the branches that cross into the bank long before
		;		WriteObjectCode has settled anything. In shared mode that is the constant
		;		PCODE_PAGE, so it can be handed over now. Embedded, it depends on ScanGPUsage --
		;		and there is no bootstrap there to copy the region either, so gpbank.asm refuses
		;		a region rather than guessing.
		;
		lda 	#(PCODE_PAGE - (FreeMemory >> 8)) & $FF
		sta 	gpBankRunPage
		stz 	gpBankShared
		lda 	ModeText 					; GPC.INPUT line 4 -- 'S' is SHARED
		cmp 	#'S'
		bne 	_CCNotShared
		inc 	gpBankShared
_CCNotShared:
		ldx 	#APIDesc & $FF
		ldy 	#APIDesc >> 8
		jsr 	StartCompiler
		bcs 	_CCStopped 					; THE COMPILE ITSELF FAILED. StartCompiler documents CC = okay
									; and CompilerErrorHandler has already printed the message and the
									; line, so there is nothing to add -- but this carry used to be
									; DROPPED, and WriteObjectCode ran anyway. A structure error out of
									; FixBranches (GP.IF with no GP.ENDIF, GP.SELECT with no GP.ENDSEL,
									; GP.EXITDO with no GP.LOOP) therefore wrote out the half-resolved
									; object -- truncated at the branch it could not fix, because
									; _FBEDNoLoop restores objPtr to it -- and then printed OK.
		jsr 	WriteObjectCode
		bcs 	_CCStopped 					; shared-mode reject (PROGRAM TOO BIG) -- also already reported
		jsr 	WriteMapFile 				; and the line#->offset map, if GPC.INPUT asked for one
		lda 	#"O" 						; the only other thing it prints, and the only way a
		jsr 	$FFD2 						; caller can tell a compile that worked from one that
		lda 	#"K" 						; stopped on an error, so it stays.
		jsr 	$FFD2
		lda 	#' '
		jsr 	$FFD2
		jmp 	PrintMemoryReport 			; ... and what it cost -- see compiler/memreport.asm

_CCStopped: 								; either half set carry and has already said why, so stop
		rts 								; here: no object, no map file, and above all no OK.

_CCNoControlFile: 							; a compiler that guesses at what it was asked to
		jmp 	PrintNoControlFile 			; build is worse than one that refuses

; ************************************************************************************************
;
;									API Setup for the compiler
;
; ************************************************************************************************

; ************************************************************************************************
;
;		THE TWO LIMITS THAT BOUND A COMPILE.  They are separate, and conflating them is what
;		made large programs miscompile in silence.
;
;		ObjectCeiling  is how far the OBJECT CODE may grow. It is written by _CAWriteByte
;		               (api.asm) from FreeMemory upwards, and $9F00 is simply where usable low
;		               RAM stops -- the I/O page. Capacity = ObjectCeiling - FreeMemory.
;
;		CompilerWorkspace{Start,End}  is where the compiler keeps its two TABLES: the variable
;		               name list growing UP from Start, the line-number table growing DOWN from
;		               End (reset.asm). This lives in BANKED RAM at $A000-$BFFF, reached through
;		               the storage_access/storage_release macros, so it does not compete with the
;		               object code for low memory.
;
;		THEY ARE A BANK EACH, so Start..End bounds them SEPARATELY rather than jointly -- 2,048
;		lines and 1,365 variables, not 8K shared. Sharing one bank made the real limit the sum of
;		the two, and samples/editor had reached 7,981 of 8,192 (1,461 lines, 356 variables): fifty
;		more lines of source raised PROGRAM TOO BIG with a third of the OBJECT budget unused. The
;		message was right, the limit behind it was the wrong one. See x16_storage.inc.
;
;		Before this was split, the workspace started at $8000 and the object code was allowed to
;		run into it unchecked: at exactly $8000-$5100 = 12,032 bytes of p-code the object code
;		began overwriting the head of the variable name list, FindVariable then failed for EVERY
;		variable, and CreateVariableRecord handed each reference a fresh slot. The compiler
;		printed OK and emitted an object in which "X" on one line and "X" on the next were
;		different variables. samples/FSIM16_V1 (12,766 bytes of p-code) tripped it by 734 bytes.
;
; ************************************************************************************************

ObjectCeiling           = $9F00 			; object code may occupy FreeMemory..ObjectCeiling-1
CompilerWorkspaceStart  = $A000 			; banked RAM: variable name table, grows up
CompilerWorkspaceEnd    = $C000 			; banked RAM: line number table, grows down

APIDesc:
		.word 	CompilerAPI 				; the compiler API Implementeation
		.byte 	CompilerWorkspaceStart >> 8 	; start of workspace for compiler
		.byte 	CompilerWorkspaceEnd >> 8 		; end of workspace for compiler

;
;		The source and object file names used to be two .text constants here. They are now the
;		first two lines of GPC.INPUT -- see file-io/control.asm.
;

		.send code

		.section storage
		.send storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		symfile.asm
;		Purpose:	Translate a GP.ASM {VAR} name through BASLOAD's #SYMFILE.
;		Created:	30th August 2026
;
; ************************************************************************************************
; ************************************************************************************************
;
;		BASLOAD RENAMES EVERY VARIABLE. N% becomes A%, which is how it offers 64 character
;		names on a two character BASIC -- and it stores REM text byte for byte, which is the
;		very property that lets a GP.ASM body survive tokenisation at all. So {N%} in a REM
;		names a variable the compiled code no longer calls N%, and an assembly block written
;		against the source spelling would read and write a slot BASIC never touches.
;
;		#SYMFILE is BASLOAD's own answer, and it is the only one that does not change the
;		syntax: it writes source name -> crunched name for every variable and label. This
;		reads it.
;
;		THE FILE FORMAT, as BASLOAD 0.2.1 writes it:
;
;			BASLOAD 0.2.1 SYMBOL FILE
;
;			LABELS
;			------
;			FILE: PROG.BASL
;			 000076 READLINE                 =160;
;
;			VARIABLES
;			---------
;			FILE: PROG.BASL
;			 000030 PR                       =A;
;			 000031 NM                       =A0;
;
;		Two things about it matter. The LABELS section has the same line shape but its values
;		are BASIC line numbers, so the scan must not start until VARIABLES has gone past or a
;		label could answer for a variable of the same name. And THE SIGIL IS NOT RECORDED --
;		PR$ is filed as PR -- because BASLOAD crunches the identifier and the $ or % rides
;		along separately, which is exactly what lets one entry serve N, N$ and N%.
;
;		The name column is padded, but nothing here assumes its width: the name ends at the
;		first space and the value runs from the "=" to the ";".
;
;		WHERE THE FILE NAME COMES FROM. It is derived from GPC.INPUT's source line, extension
;		replaced by .SYM -- so compiling PROG.PRG reads PROG.SYM. That is the convention
;		source/gpc/build_basl.py already follows ("a #SYMFILE, if any, sits beside the PRG"),
;		and it means nothing new has to be typed or carried in GPC.INPUT. The source file has
;		to say
;
;			#SYMFILE "@:PROG.SYM"
;
;		at the top, which is where BASLOAD requires it anyway.
;
;		IT IS READ WHILE THE SOURCE FILE IS OPEN, because {VAR} is resolved mid-compile. Hence
;		its own logical file and a CHKIN back to 3 on the way out -- the compiler is part way
;		through reading a line and would otherwise carry on reading the symbol file instead.
;
; ************************************************************************************************

		.section code

IO_SYM_FILE = 5 							; 3 is the source, 4 the runtime image at write time

; ************************************************************************************************
;
;		Look AsmSymName up. CC and AsmSymCrunched set if found; CS with A=0 if there is no
;		symbol file at all and A=1 if the name is not in it.
;
; ************************************************************************************************

SymbolLookup:
		jsr 	SymBuildName 				; <source>.SYM -> SymFileName
		lda 	#IO_SYM_FILE
		sta 	ioFileNo
		lda 	#'R'
		ldx 	#SymFileName & $FF
		ldy 	#SymFileName >> 8
		jsr 	IOSetFileName 				; carry comes back from OPEN
		ldy 	#3
		sty 	ioFileNo 					; put the default back for every other caller
		bcc 	_SLOpened
		lda 	#0 							; no symbol file at all -- the caller says which
		sec 								; of the two errors that is
		rts
_SLOpened:
		ldx 	#IO_SYM_FILE
		jsr 	$FFC6 						; CHKIN
		stz 	symInVariables
		;
		;		THE OPEN TELLS YOU NOTHING. CMDR-DOS, like every CBM DOS before it, opens a file
		;		that is not there quite happily and only reports it on the first read -- so a
		;		missing symbol file arrives here looking exactly like an empty one, and would
		;		be reported as "the name is not in it" rather than "there isn't one".
		;
		;		The banner settles it: every symbol file starts "BASLOAD n.n.n SYMBOL FILE", so
		;		a first line that does not begin BASLOAD means there is no symbol file to read
		;		-- whether because it is absent, empty, or is some other file entirely.
		;
		jsr 	SymReadLine
		bcs 	_SLNotSymFile
		ldx 	#0
_SLBanner:
		lda 	_SLBaslText,x
		beq 	_SLIsSymFile 				; matched the whole word
		cpx 	symLineLen
		bcs 	_SLNotSymFile
		cmp 	symLine,x
		bne 	_SLNotSymFile
		inx
		bra 	_SLBanner
_SLNotSymFile:
		jsr 	SymClose
		lda 	#0
		sec
		rts
_SLBaslText:
		.text 	"BASLOAD", 0
_SLIsSymFile:
_SLLine:
		jsr 	SymReadLine 				; CS at end of file
		bcc 	_SLHaveLine
		jmp 	_SLNotFound 				; past the end of the parse, so out of branch range
_SLHaveLine:
		lda 	symLineLen
		beq 	_SLLine 					; blank
		lda 	symLine 					; a data line starts with a space, a section
		cmp 	#' ' 						; heading does not
		beq 	_SLData
		ldx 	#0 							; is it the VARIABLES heading ?
_SLHeading:
		lda 	_SLVariablesText,x
		beq 	_SLIsVariables 				; matched the whole word
		cmp 	symLine,x
		bne 	_SLLine 					; some other heading -- LABELS, FILE:, the banner
		inx
		bra 	_SLHeading
_SLIsVariables:
		lda 	#1
		sta 	symInVariables
		bra 	_SLLine
		;
		;		Every rejection below goes back through here: the head of the loop is out of
		;		branch range from the far end of the parse.
		;
_SLNextLine:
		jmp 	_SLLine
		;
		;		" 000030 PR                       =A;"  -- skip the space and the line number,
		;		compare the name, then take what lies between = and ;.
		;
_SLData:
		lda 	symInVariables
		beq 	_SLNextLine 					; still in LABELS, where the values are line numbers
		ldx 	#1 							; past the leading space
_SLSkipNum:
		lda 	symLine,x
		cmp 	#' '
		beq 	_SLAtName
		inx
		cpx 	symLineLen
		bcc 	_SLSkipNum
		bra 	_SLNextLine 					; malformed -- no second space
_SLAtName:
		inx 								; first character of the name
		ldy 	#0
_SLCompare:
		lda 	symLine,x
		cmp 	#' '
		beq 	_SLNameEnd 					; the file's name has ended
		cmp 	AsmSymName,y
		bne 	_SLNextLine 					; differs
		inx
		iny
		cpx 	symLineLen
		bcc 	_SLCompare
		bra 	_SLNextLine
_SLNameEnd:
		lda 	AsmSymName,y 				; ...and ours must end in the same place, or PR
		bne 	_SLNextLine 					; would answer for PRINTER
		;
		;		Matched. The crunched name is between the "=" and the ";".
		;
_SLFindEquals:
		lda 	symLine,x
		cmp 	#'='
		beq 	_SLAtValue
		inx
		cpx 	symLineLen
		bcc 	_SLFindEquals
		bra 	_SLNextLine 					; malformed -- no value
_SLAtValue:
		inx
		ldy 	#0
_SLValue:
		lda 	symLine,x
		cmp 	#';'
		beq 	_SLGotValue
		cpy 	#2 							; BASLOAD crunches to one or two characters; more
		bcs 	_SLNextLine 					; than that is not a name this BASIC could hold
		sta 	AsmSymCrunched,y
		iny
		inx
		cpx 	symLineLen
		bcc 	_SLValue
		bra 	_SLNextLine
_SLGotValue:
		cpy 	#0
		beq 	_SLNextLine 					; "=;" -- nothing there
		lda 	#0
		sta 	AsmSymCrunched,y 			; terminate: one character leaves the second zero
		jsr 	SymClose
		clc
		rts

_SLNotFound:
		jsr 	SymClose
		lda 	#1 							; there is a symbol file, the name is not in it
		sec
		rts

_SLVariablesText:
		.text 	"VARIABLES", 0

; ************************************************************************************************
;
;		Close the symbol file and give the source file the input channel back -- the compiler
;		is part way through reading a line and everything after this reads from it again.
;
; ************************************************************************************************

SymClose:
		lda 	#IO_SYM_FILE
		jsr 	$FFC3 						; CLOSE
		ldx 	#3
		jmp 	$FFC6 						; CHKIN the source

; ************************************************************************************************
;
;		Read one line into symLine, length in symLineLen, CS at end of file. Anything past the
;		buffer is dropped rather than wrapped -- a symbol file line is a number, a name and a
;		short value, and a longer one cannot be a variable this BASIC could hold anyway.
;
; ************************************************************************************************

SymReadLine:
		stz 	symLineLen
_SRLByte:
		jsr 	IOReadByte
		bcs 	_SRLEnd
		cmp 	#13 						; CR or LF ends it -- written on the X16, but a
		beq 	_SRLDone 					; symbol file that has been through a host tool
		cmp 	#10 						; should still read
		beq 	_SRLDone
		ldx 	symLineLen
		cpx 	#SYM_LINE_MAX
		bcs 	_SRLByte 					; over length: keep reading, stop storing
		sta 	symLine,x
		inc 	symLineLen
		bra 	_SRLByte
_SRLDone:
		clc
		rts
_SRLEnd:
		lda 	symLineLen 					; a last line with no terminator is still a line
		beq 	_SRLReallyEnd
		clc
		rts
_SRLReallyEnd:
		sec
		rts

; ************************************************************************************************
;
;		SourceFile with its extension replaced by .SYM. No extension, and .SYM is appended --
;		which is what a source called PROG (no dot) would want.
;
; ************************************************************************************************

SymBuildName:
		ldx 	#0
		ldy 	#0 							; Y = length up to and including the last dot, 0 = none
_SBNCopy:
		lda 	SourceFile,x
		beq 	_SBNEnd
		sta 	SymFileName,x
		cmp 	#'.'
		bne 	_SBNNext
		txa
		tay
		iny 								; keep the dot itself
_SBNNext:
		inx
		cpx 	#CFLineSize
		bne 	_SBNCopy
_SBNEnd:
		cpy 	#0
		beq 	_SBNAppend 					; no dot at all -- append ".SYM" to the whole name
		tya
		tax
		bra 	_SBNSuffix
_SBNAppend:
		lda 	#'.'
		sta 	SymFileName,x
		inx
_SBNSuffix:
		ldy 	#0
_SBNCopySuffix:
		lda 	_SBNSymText,y
		sta 	SymFileName,x
		beq 	_SBNDone
		inx
		iny
		bra 	_SBNCopySuffix
_SBNDone:
		rts

_SBNSymText:
		.text 	"SYM", 0

SYM_LINE_MAX = 96 							; number, name and value; the name column is padded

symLine: 									; code section, like everything else the compiler
		.fill 	SYM_LINE_MAX 				; owns -- thrown away with it, so it costs a
symLineLen: 								; compiled program nothing. See file-io/read.asm.
		.fill 	1
symInVariables: 							; past the VARIABLES heading, where the values stop
		.fill 	1 						; being line numbers and start being names
SymFileName:
		.fill 	CFLineSize+8

		.send code

